// スキルルーンの効果候補と抽選確率
// 出典: 公式wiki の各スキル個別ページ（2026-08-23 取得）
//
// - 等級内の各効果の登場確率は同一（= 等級確率 ÷ 効果数）
// - レジェンド以下のスキル: レジェンド効果は1つのみ登場する
// - スタースキル: レジェンド効果とスター効果は、どちらかが最大1つのみ登場する
// - ルーンの等級（中級・上級）は効果の登場確率に影響せず、オプションの枠数が変わる
//   （中級 3枠 / 上級 4枠）

export const runeTiers = ['Magic', 'Rare', 'Unique', 'Epic', 'Legend', 'Star'] as const;
export type RuneTier = typeof runeTiers[number];

export interface RuneTierEffects {
  tier: RuneTier;
  /** その等級が出る確率（0〜1） */
  probability: number;
  /** その等級で出うる効果。等級内では等確率 */
  effects: string[];
}

/** ルーンの等級ごとのオプション枠数 */
export const runeSlotCounts = { intermediate: 3, advanced: 4 } as const;
export type RuneGrade = keyof typeof runeSlotCounts;

